package com.hrms.attendance.controller;

import com.hrms.attendance.dto.*;import com.hrms.attendance.model.AttendanceStatus;import com.hrms.attendance.service.AttendanceService;import com.hrms.auth.security.AuthPrincipal;import com.hrms.common.responses.*;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.validation.Valid;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.time.LocalDate;
@RestController @RequestMapping("/api/v1/admin/attendance") @Tag(name="Admin attendance") @SecurityRequirement(name="bearerAuth") @PreAuthorize("hasRole('ADMIN')")
public class AdminAttendanceController {private final AttendanceService service;private final ClockSource clock;public AdminAttendanceController(AttendanceService s,ClockSource c){service=s;clock=c;}
 @GetMapping public ApiResponse<AttendancePageResponse> list(@RequestParam(required=false)String employeeId,@RequestParam(required=false)String employeeCode,@RequestParam(required=false)String departmentId,@RequestParam(required=false)String officeLocationId,@RequestParam(required=false)String shiftId,@RequestParam(required=false)AttendanceStatus status,@RequestParam(required=false)LocalDate fromDate,@RequestParam(required=false)LocalDate toDate,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int limit,@RequestParam(defaultValue="workDate")String sortBy,@RequestParam(defaultValue="desc")String sortDirection){return ApiResponse.success("Attendance records retrieved",service.list(new AttendanceSearch(employeeId,employeeCode,departmentId,officeLocationId,shiftId,status,fromDate,toDate,page,limit,sortBy,sortDirection)),clock);}
 @GetMapping("/summary") public ApiResponse<AttendanceSummaryResponse> summary(@RequestParam(required=false)String employeeId,@RequestParam(required=false)String employeeCode,@RequestParam(required=false)String departmentId,@RequestParam(required=false)String officeLocationId,@RequestParam(required=false)String shiftId,@RequestParam(required=false)AttendanceStatus status,@RequestParam(required=false)LocalDate fromDate,@RequestParam(required=false)LocalDate toDate){return ApiResponse.success("Attendance summary retrieved",service.summary(new AttendanceSearch(employeeId,employeeCode,departmentId,officeLocationId,shiftId,status,fromDate,toDate,0,100, "workDate","desc")),clock);}
 @GetMapping("/{attendanceId}") public ApiResponse<AttendanceResponse> detail(@PathVariable String attendanceId){return ApiResponse.success("Attendance record retrieved",service.detail(attendanceId),clock);}
 @PatchMapping("/{attendanceId}/correction") public ApiResponse<AttendanceResponse> correct(@PathVariable String attendanceId,@Valid @RequestBody AttendanceCorrectionRequest r,@AuthenticationPrincipal AuthPrincipal p){return ApiResponse.success("Attendance corrected",service.correct(attendanceId,r,p),clock);}
}
